import pytest
from target import sliding_window


class TestSlidingWindow:
    def test_empty_string_returns_zero(self):
        assert sliding_window("") == 0

    def test_single_character_returns_one(self):
        assert sliding_window("a") == 1

    def test_all_unique_characters(self):
        assert sliding_window("abcde") == 5

    def test_all_same_characters(self):
        assert sliding_window("aaaa") == 1

    def test_repeated_characters_with_gaps(self):
        # "abcabcbb" -> longest substring without repeating chars is "abca" (len 3) or "bcabc" no...
        # Let's compute: a b c a b c b b
        # Longest is "abc" (3) or "cb a" -> actually "abcabcbb" has max 3
        assert sliding_window("abcabcbb") == 3

    def test_input_type_error_for_integer(self):
        with pytest.raises(TypeError, match="Input must be a string"):
            sliding_window(123)

    def test_input_type_error_for_none(self):
        with pytest.raises(TypeError, match="Input must be a string"):
            sliding_window(None)

    def test_input_type_error_for_list(self):
        with pytest.raises(TypeError, match="Input must be a string"):
            sliding_window(["a"])

    def test_two_characters_same(self):
        assert sliding_window("aa") == 1

    def test_two_characters_different(self):
        assert sliding_window("ab") == 2

    def test_substring_with_repeats(self):
        # "dvdf" -> d v d f -> max is 3 (vdf or dvf)
        assert sliding_window("dvdf") == 3

    def test_longer_example(self):
        # "pwwkew" -> longest is "wke" or "kew" -> 3
        assert sliding_window("pwwkew") == 3

    def test_only_spaces(self):
        assert sliding_window("   ") == 1

    def test_mixed_spaces_and_chars(self):
        # "a b a" -> spaces are distinct chars? No, space is a char.
        # "a b a": a, space, b, space, a -> longest without repeat: "a b" (3) then next space repeats space at index 1.
        # At index 3 (space), previous space at index 1 >= left(0), so left = 2. Current: b, space -> len 2.
        # At index 4 (a), previous a at index 0 < left(2), so no update. Current: b, space, a -> len 3.
        # Max is 3.
        assert sliding_window("a b a") == 3

    def test_binary_string(self):
        assert sliding_window("010101") == 2

    def test_longer_string(self):
        # "abba" -> longest without repeat is "ab" or "ba" -> 2
        assert sliding_window("abba") == 2

