        assert sliding_window("") == 0

    def test_single_character(self):
        assert sliding_window("a") == 1

    def test_all_same_characters(self):
        assert sliding_window("aaaa") == 1

    def test_no_repeating_characters(self):
        assert sliding_window("abcdef") == 6

    def test_abcabc(self):
        assert sliding_window("abcabc") == 3

    def test_txyz(self):
        assert sliding_window("txyz") == 4

    def test_pwwkew(self):
        assert sliding_window("pwwkew") == 3

    def test_abcbbbbd(self):
        assert sliding_window("abcbbbbd") == 4

    def test_bbbbbb(self):
        assert sliding_window("bbbbbb") == 1

    def test_pwwke(self):
        assert sliding_window("pwwke") == 3

    def test_longer_example(self):
        # "abcabcbb" -> longest substring without repeating is "abc"
        assert sliding_window("abcabcbb") == 3

    def test_mixed_case(self):
        # 'a' and 'A' are different characters
        assert sliding_window("aAbBcC") == 6

    def test_two_characters_no_repeat(self):
        assert sliding_window("ab") == 2

    def test_two_characters_same(self):
        assert sliding_window("aa") == 1

    def test_unicode_characters(self):
        assert sliding_window("héllo") == 3  # é appears once, h,é,l are unique, l repeats

    def test_non_string_integer(self):
        with pytest.raises(TypeError):
            sliding_window(123)

    def test_non_string_none(self):
        with pytest.raises(TypeError):
            sliding_window(None)

    def test_non_string_list(self):
        with pytest.raises(TypeError):
            sliding_window(["a", "b", "c"])

    def test_non_string_bytes(self):
        with pytest.raises(TypeError):
            sliding_window(b"hello")

    def test_whitespace_string(self):
        assert sliding_window("   ") == 1

    def test_whitespace_and_letters(self):
        # " a b " -> spaces repeat, so longest unique substring
        # Let's pick a known case: " a b " length 5
        # positions: 0=' ',1='a',2=' ',3='b',4=' '
        # At pos 2, space repeats from pos 0, window starts at 1, length = 2-1+1=2
        # At pos 4, space repeats from pos 2, window starts at 3, length = 4-3+1=2
        # Max is 2? Actually "a " or " b " has length 2.
        assert sliding_window(" a b ") == 2

    def test_large_string(self):
        # All unique characters
        s = "abcdefghijklmnopqrstuvwxyz"
        assert sliding_window(s) == 26

